<script setup lang="ts">
import { ref } from 'vue'
import { useRouter } from 'vue-router'
import { apiFetch, token } from '../auth'
const router = useRouter(); const type = ref('film'); const title = ref(''); const description = ref(''); const coverUrl = ref(''); const externalUrl = ref(''); const tags = ref(''); const message = ref(''); const error = ref('')
async function submit() { if (!token.value) { error.value = '请先登录'; return } const response = await apiFetch('/api/contents', { method: 'POST', body: JSON.stringify({ type: type.value, title: title.value, description: description.value, cover_url: coverUrl.value, external_url: externalUrl.value || null, tags: tags.value.split(',').map(item => item.trim()).filter(Boolean) }) }); const data = await response.json(); if (!response.ok) { error.value = data.detail || '发布失败'; return } message.value = '已提交审核，审核通过后会展示在分类页面。'; title.value = ''; description.value = ''; await router.push('/') }
</script>
<template><section class="publish-shell"><p class="eyebrow">SHARE A RECOMMENDATION</p><h1>发布安利</h1><p>内容提交后会进入管理员审核。</p><form class="publish-form" @submit.prevent="submit"><input v-model="title" placeholder="标题" required /><select v-model="type"><option value="film">影视</option><option value="dance">舞蹈</option><option value="image">图片</option><option value="song">歌曲</option><option value="fanwork">二创</option></select><textarea v-model="description" placeholder="写下你的安利理由" required /><input v-model="coverUrl" placeholder="封面地址（可选）" /><input v-model="externalUrl" placeholder="外部链接（可选）" /><input v-model="tags" placeholder="标签，用逗号分隔，最多 5 个" /><p v-if="error" class="form-error">{{ error }}</p><p v-if="message" class="success-message">{{ message }}</p><button type="submit">提交审核</button></form></section></template>
